input.command:
cd /tmp/emit
runs() { printf '%s' "v: \"$1\"" > c.in; printf 'STR=[%s] -> ' "$2"; O=$(/workspace/dataset/test20_executable --a "$(cat c.in)" 2>/dev/null); rc=$?; printf 'rc=%s OUT=' "$rc"; printf '%s' "$O" | od -An -c | tr -d '\n'; echo; }
for s in '-' '?' ':' '!' '&' '*' '#' '|' '>' '%' '@' '`' "'" '{' '}' '[' ']' ',' '\"' '\\\\' '$' '(' ')' '+' '.' '/' '_' '~x' '=x' ; do runs "$s" "$s"; done

cd /tmp/emit
mk() { n=$1; s=$(printf 'a%.0s' $(seq 1 $n)); printf '%s' "{\"$s\": 1}" > k.in; O=$(/workspace/dataset/test20_executable --a "$(cat k.in)" 2>/dev/null); rc=$?; first=$(printf '%s' "$O" | head -c 4); nl=$(printf '%s' "$O" | wc -l); printf 'keylen=%-4s rc=%s first4=[%s] lines=%s\n' "$n" "$rc" "$first" "$nl"; }
for n in 1 100 126 127 128 129 130 200; do mk $n; done

cd /tmp/emit
mk() { n=$1; s=$(printf 'a%.0s' $(seq 1 $n)); printf '%s' "{\"$s\": 1}" > k.in; O=$(/workspace/dataset/test20_executable --a "$(cat k.in)" 2>/dev/null); printf 'keylen=%-4s first2=[%s]\n' "$n" "$(printf '%s' "$O" | cut -c1-2)"; }
for n in 118 119 120 121 122 123 124 125; do mk $n; done

cd /tmp/emit
q() { printf '%s' "v: \"$1\"" > n.in; O=$(/workspace/dataset/test20_executable --a "$(cat n.in)" 2>/dev/null); rc=$?; printf '%-14s rc=%s -> %s\n' "[$1]" "$rc" "$(printf '%s' "$O" | cat -A | tr '\n' '@')"; }
for s in '---x' '...x' '..' '--' '-.' '. ' '.-' 'a\\r\\nb' 'a\\rb' '\\r' '\\n\\r' '\\r\\n' 'x\\t' '\\t\\n' '\\n\\t' ' \\n' '\\n ' 'a\\n\\tb' 'a-\\nb' '\\n#' '\\n-'; do q "$s"; done

input.new_string:
* `0x100 <= cp <= 0xFFFF` → `\uHHHH` (4 hex digits, uppercase). Verified code point → literal
  output text: U+0100 → `Ā`; U+4E2D (CJK 中) → `中`; U+FFFD → `�`;
  U+FFFE → `￾`; U+FFFF → `￿`; U+FEFF (BOM) → `﻿`; U+E000 → ``;
  U+D7FF → `퟿`; lone surrogate U+D800 → `\uD800`.
* `cp > 0xFFFF` → `\UHHHHHHHH` (8 hex digits, uppercase): U+1F600 (emoji) → `\U0001F600`;
  U+10FFFF → `\U0010FFFF`.

Examples (LHS = the Python string, RHS = literal output bytes):
`café` → `v: "caf\xE9"$@$@`; `中文` (U+4E2D U+6587) → `v: "中文"$@$@`;
`a` U+00E9 `b` U+4E2D `c` → `v: "a\xE9b中c"$@$@`; U+FEFF + `x` → `v: "﻿x"$@$@`;
`a` U+0085 `b` → `v: "a\Nb"$@$@`; `a` U+00A0 `b` → `v: "a\_b"$@$@`;
`a` U+2028 `b` → `v: "a\Lb"$@$@`; `a` U+2029 `b` → `v: "a\Pb"$@$@`.
